<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -subj</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/CN=LDAP-CA/O=Example/C=US&quot;</span></span>
