<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -extfile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;subjectAltName=DNS:localhost,IP:127.0.0.1&quot;)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
